  XW += x[10] * 2.5029999999999998e+01; // C2H
  XW += x[11] * 2.6037999999999997e+01; // C2H2
  XW += x[12] * 2.7045999999999999e+01; // C2H3
  XW += x[13] * 2.8053999999999998e+01; // C2H4
  XW += x[14] * 2.9061999999999998e+01; // C2H5
  XW += x[15] * 3.0070000000000000e+01; // C2H6
  XW += x[16] * 3.8048999999999999e+01; // C3H2
  XW += x[17] * 3.9057000000000002e+01; // C3H3
  XW += x[18] * 4.0064999999999998e+01; // C3H4A
  XW += x[19] * 4.0064999999999998e+01; // C3H4P
  XW += x[20] * 4.1073000000000000e+01; // C3H5
  XW += x[21] * 4.1073000000000000e+01; // C3H5A
  XW += x[22] * 4.2081000000000003e+01; // C3H6
  XW += x[23] * 4.3088999999999999e+01; // C3H7(n)
  XW += x[24] * 5.0059999999999995e+01; // C4H2
  XW += x[25] * 5.1067999999999998e+01; // H2CCCCH
  XW += x[26] * 5.2075999999999993e+01; // C4H4(13)
