  // reaction 30: C2H5 + H <=> C2H6
  qf[30] = sc[2] * sc[14];
  qr[30] = sc[15];

  // reaction 31: C2H4 <=> C2H2 + H2
  qf[31] = sc[13];
  qr[31] = sc[1] * sc[11];

  // reaction 32: C2H3 + H <=> C2H2 + H2
